'use client';

import * as React from 'react';
import { Toolbar as BaseToolbar } from '@base-ui/react/toolbar';
import { Toggle } from '@base-ui/react/toggle';
import { Tooltip, TooltipProvider } from '../tooltip/tooltip';
import { Kbd } from '../kbd/kbd';
import './toolbar.css';

/* ─────────────────────────────────────────────────────────
 * TOOLBAR and TOOL BUTTON on Base UI Toolbar + Toggle + Tooltip
 *   enter     one nest from its edge on the surface spring
 *   hover     the glyph plays its pose (the tool is its trigger); a tooltip after 120 ms: "Select · V"
 *   press     down 1 into a well, 50 ms; back on release
 *   latched   stays pressed, a 4 pt green LED top right; state changes at once
 *   focus     a 1.5 ring with no offset (a dense strip); arrows move between tools
 * ───────────────────────────────────────────────────────── */

export interface ToolbarProps {
  /** frost (the colorway's frosted strip) or graphite (the dark strip, in both colorways). */
  variant?: 'frost' | 'graphite';
  'aria-label': string;
  className?: string;
  children: React.ReactNode;
}

/** A strip of tools: 48 tall, a capsule. */
export function Toolbar({ variant = 'frost', className, children, ...props }: ToolbarProps) {
  return (
    <TooltipProvider>
      <BaseToolbar.Root
        aria-label={props['aria-label']}
        data-variant={variant}
        className={['mu-toolbar', variant === 'graphite' ? 'mu-frost-graphite' : 'mu-frost-strip', className].filter(Boolean).join(' ')}
      >
        {children}
      </BaseToolbar.Root>
    </TooltipProvider>
  );
}

export interface ToolButtonProps {
  /** The tool's name: its accessible name and tooltip. */
  label: string;
  /** The key, in the tooltip and aria-keyshortcuts: "V". */
  shortcut?: string;
  /** The glyph at 16, e.g. <SelectIcon size={16} />. */
  icon: React.ReactNode;
  /** Latched (the active tool). Omit for a momentary action. */
  pressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  onClick?: () => void;
  disabled?: boolean;
}

/** A circular tool cap. Latched tools sit pressed with a green LED. */
export function ToolButton({ label, shortcut, icon, pressed, onPressedChange, onClick, disabled }: ToolButtonProps) {
  const button = pressed === undefined ? (
    <BaseToolbar.Button className="mu-tool mu-icon-trigger" aria-label={label} aria-keyshortcuts={shortcut} disabled={disabled} onClick={onClick}>
      {icon}
    </BaseToolbar.Button>
  ) : (
    <BaseToolbar.Button
      render={<Toggle pressed={pressed} onPressedChange={(p) => onPressedChange?.(p)} />}
      className="mu-tool mu-icon-trigger"
      aria-label={label}
      aria-keyshortcuts={shortcut}
      disabled={disabled}
      onClick={onClick}
    >
      {icon}
    </BaseToolbar.Button>
  );
  return <Tooltip label={label} shortcut={shortcut}>{button}</Tooltip>;
}

/** An engraved rule between groups of tools. */
export function ToolbarSeparator() {
  return <BaseToolbar.Separator className="mu-toolbar-sep" />;
}

export interface ToolbarSearchProps {
  /** Opens the command palette. */
  onOpen: () => void;
  placeholder?: string;
  icon?: React.ReactNode;
  shortcut?: string;
}

/** The search well in the strip: opens the palette. */
export function ToolbarSearch({ onOpen, placeholder = 'Search or ask', icon, shortcut = '⌘K' }: ToolbarSearchProps) {
  return (
    <BaseToolbar.Button className="mu-toolbar-search" onClick={onOpen} aria-keyshortcuts="Meta+K">
      {icon}
      {placeholder}
      <Kbd surface="strip">{shortcut}</Kbd>
    </BaseToolbar.Button>
  );
}

@import "../tokens.css";
@import "../kbd/kbd.css";
@import "../tooltip/tooltip.css";

/* Toolbar and tool button on Base UI Toolbar and Toggle. */
.mu-toolbar {
  display: inline-flex;
  align-items: center;
  gap: var(--mu-toolbar-gap);
  padding: var(--mu-toolbar-pad);
  border-radius: var(--mu-radius-card);
  /* Enters one nest from its edge on the surface spring. */
  animation: mu-toolbar-in var(--mu-spring-surface-d) var(--mu-spring-surface) both;
}
@keyframes mu-toolbar-in { from { opacity: 0; transform: translateY(calc(var(--mu-motion-nest) * var(--mu-travel-surface))); } }
.mu-tool {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--mu-toolbar-tool);
  height: var(--mu-toolbar-tool);
  padding: var(--mu-zero);
  border: 0;
  border-radius: var(--mu-round);
  color: var(--mu-icon);
  background: var(--mu-btn-bg);
  box-shadow: var(--mu-btn-sh);
  cursor: pointer;
  /* A tool's state is instant (it changes a hundred times a day); only the press travels, on release. */
  transition: transform var(--mu-spring-release-d) var(--mu-spring-release);
  -webkit-tap-highlight-color: transparent;
}
.mu-tool > svg { width: var(--mu-toolbar-glyph); height: var(--mu-toolbar-glyph); }
.mu-tool:hover { color: var(--mu-ink); }
.mu-tool:active, .mu-tool[data-pressed] { transform: translateY(var(--mu-motion-press)); background: var(--mu-pressed-bg); box-shadow: var(--mu-pressed-sh); color: var(--mu-ink); }
.mu-tool:active { transition-duration: var(--mu-r-toolbar-tool-press-time); }
.mu-tool[data-pressed]::after {
  content: "";
  position: absolute;
  top: var(--mu-toolbar-led-inset);
  right: var(--mu-toolbar-led-inset);
  width: var(--mu-toolbar-led);
  height: var(--mu-toolbar-led);
  border-radius: var(--mu-round);
  background: var(--mu-led-green);
  box-shadow: var(--mu-led-ring), var(--mu-status-bloom);
}
.mu-tool:focus-visible { outline: var(--mu-segmented-focus-width) solid var(--mu-focus); outline-offset: 0; }
.mu-tool[data-disabled] { opacity: .4; cursor: default; }
.mu-toolbar-sep { width: var(--mu-r-toolbar-sep-width); height: var(--mu-toolbar-sep-height); margin: var(--mu-zero) var(--mu-r-toolbar-sep-margin); background: var(--mu-rule); box-shadow: var(--mu-rule-lip-shadow); }
.mu-toolbar-search {
  display: flex;
  align-items: center;
  gap: var(--mu-r-toolbar-search-gap);
  height: var(--mu-toolbar-tool);
  min-width: var(--mu-toolbar-search-min);
  padding: var(--mu-zero) var(--mu-r-toolbar-search-pad-right) var(--mu-zero) var(--mu-r-toolbar-search-pad-left);
  border: 0;
  border-radius: var(--mu-radius-pill);
  font: var(--mu-type-ui);
  letter-spacing: var(--mu-type-ui-tracking);
  color: var(--mu-ink3);
  background: linear-gradient(var(--mu-well-top), var(--mu-well-bot));
  box-shadow: var(--mu-well);
  cursor: text;
}
.mu-toolbar-search > svg { width: 14px; height: 14px; }
.mu-toolbar-search > .mu-kbd { margin-left: auto; }
.mu-toolbar-search:focus-visible { outline: var(--mu-segmented-focus-width) solid var(--mu-focus); outline-offset: 0; }

/* Graphite: the graphite dock, dark in both colorways; its look is the toolbar recipe (--mu-r-toolbar-*, the demo's #toolbar). */
.mu-toolbar[data-variant="graphite"] {
  gap: var(--mu-r-toolbar-self-gap);
  padding: var(--mu-r-toolbar-self-pad);
  border-radius: var(--mu-r-toolbar-self-radius);
  background: var(--mu-r-toolbar-self-background);
  box-shadow: var(--mu-r-toolbar-self-shadow);
  -webkit-backdrop-filter: var(--mu-r-toolbar-self-blur);
  backdrop-filter: var(--mu-r-toolbar-self-blur);
}
.mu-toolbar[data-variant="graphite"] .mu-tool {
  width: var(--mu-r-toolbar-tool-size);
  height: var(--mu-r-toolbar-tool-size);
  border-radius: var(--mu-r-toolbar-tool-radius);
  color: var(--mu-r-toolbar-tool-ink);
  background: var(--mu-r-toolbar-tool-background);
  box-shadow: var(--mu-r-toolbar-tool-shadow);
  transition: transform var(--mu-r-toolbar-tool-press-time) linear, box-shadow var(--mu-r-toolbar-tool-shadow-time) var(--mu-ease-press);
}
.mu-toolbar[data-variant="graphite"] .mu-tool > svg { width: var(--mu-r-toolbar-tool-glyph); height: var(--mu-r-toolbar-tool-glyph); }
.mu-toolbar[data-variant="graphite"] .mu-tool:hover { color: var(--mu-r-toolbar-tool-ink); }
.mu-toolbar[data-variant="graphite"] .mu-tool:is(:active, [data-pressed]) {
  transform: translateY(var(--mu-r-toolbar-tool-press));
  background: var(--mu-r-toolbar-tool-pressed-background);
  box-shadow: var(--mu-r-toolbar-tool-pressed-shadow);
  color: var(--mu-r-toolbar-tool-ink);
}
.mu-toolbar[data-variant="graphite"] .mu-tool[data-pressed]::after {
  top: var(--mu-r-toolbar-led-inset);
  right: var(--mu-r-toolbar-led-inset);
  width: var(--mu-r-toolbar-led-size);
  height: var(--mu-r-toolbar-led-size);
  background: var(--mu-r-toolbar-led-background);
  box-shadow: var(--mu-r-toolbar-led-shadow);
}
.mu-toolbar[data-variant="graphite"] .mu-toolbar-sep {
  height: var(--mu-r-toolbar-sep-height);
  margin: var(--mu-zero) var(--mu-r-toolbar-sep-margin);
  background: var(--mu-r-toolbar-sep-background);
  box-shadow: var(--mu-r-toolbar-sep-shadow);
}
.mu-toolbar[data-variant="graphite"] .mu-toolbar-search {
  height: var(--mu-r-toolbar-search-height);
  min-width: var(--mu-r-toolbar-search-min-width);
  padding: var(--mu-zero) var(--mu-r-toolbar-search-pad-right) var(--mu-zero) var(--mu-r-toolbar-search-pad-left);
  gap: var(--mu-r-toolbar-search-gap);
  border-radius: var(--mu-r-toolbar-search-radius);
  font: var(--mu-r-toolbar-search-font);
  letter-spacing: var(--mu-type-content-tracking);
  color: var(--mu-r-toolbar-search-ink);
  background: var(--mu-r-toolbar-search-background);
  box-shadow: var(--mu-r-toolbar-search-shadow);
}
.mu-toolbar[data-variant="graphite"] .mu-toolbar-search > svg { width: var(--mu-r-toolbar-search-glyph); height: var(--mu-r-toolbar-search-glyph); }
.mu-toolbar[data-variant="graphite"] .mu-toolbar-search .mu-kbd { color: var(--mu-r-toolbar-kbd-ink); background: var(--mu-r-toolbar-kbd-background); box-shadow: var(--mu-r-toolbar-kbd-shadow); }

/* On the frost strip the search well's keycap is the light cap. */
.mu-toolbar[data-variant="frost"] .mu-toolbar-search .mu-kbd { color: var(--mu-ink2); background: var(--mu-cap-bg); box-shadow: var(--mu-cap-sh); }
